package com.robisa693.onlinefriends;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup(FriendsOnlineConfig.GROUP)
public interface FriendsOnlineConfig extends Config
{
    String GROUP = "friendsonline";

    @ConfigSection(
        name = "Display",
        description = "Display settings for the overlay",
        position = 0
    )
    String displaySection = "display";

    @ConfigSection(
        name = "Categories",
        description = "Which categories to show",
        position = 1
    )
    String categoriesSection = "categories";

    @ConfigSection(
        name = "Appearance",
        description = "Visual settings for the overlay",
        position = 2
    )
    String appearanceSection = "appearance";

    @Range(min = 0, max = 120)
    @ConfigItem(
        keyName = "displayTime",
        name = "Display Time (seconds)",
        description = "How many seconds the overlay stays visible before hiding (0 = never hide)",
        section = displaySection,
        position = 0
    )
    default int displayTime()
    {
        return 15;
    }

    @ConfigItem(
        keyName = "showWorld",
        name = "Show World",
        description = "Show world numbers next to player names",
        section = displaySection,
        position = 1
    )
    default boolean showWorld()
    {
        return true;
    }

    @Range(min = 0, max = 100)
    @ConfigItem(
        keyName = "maxPlayers",
        name = "Max Players",
        description = "Maximum number of players to show per category (0 = no limit)",
        section = displaySection,
        position = 2
    )
    default int maxPlayers()
    {
        return 20;
    }

    @ConfigItem(
        keyName = "showFriends",
        name = "Show Friends",
        description = "Show online friends from your friends list",
        section = categoriesSection,
        position = 0
    )
    default boolean showFriends()
    {
        return true;
    }

    @ConfigItem(
        keyName = "showClanChat",
        name = "Show Clan Chat",
        description = "Show members currently in your clan chat channel",
        section = categoriesSection,
        position = 1
    )
    default boolean showClanChat()
    {
        return true;
    }

    @ConfigItem(
        keyName = "showFriendsChat",
        name = "Show Chat Channel",
        description = "Show members currently in your chat channel",
        section = categoriesSection,
        position = 2
    )
    default boolean showFriendsChat()
    {
        return true;
    }

    @ConfigItem(
        keyName = "showRanks",
        name = "Show Ranks",
        description = "Show rank icons next to player names in clan chat and chat channel",
        section = appearanceSection,
        position = 0
    )
    default boolean showRanks()
    {
        return true;
    }

    @ConfigItem(
        keyName = "sortMode",
        name = "Sort Mode",
        description = "How to sort players within each category",
        section = appearanceSection,
        position = 1
    )
    default SortMode sortMode()
    {
        return SortMode.ALPHABETICAL;
    }

    enum SortMode
    {
        ALPHABETICAL,
        RANK,
        WORLD
    }
}

package com.robisa693.onlinefriends;

import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.Friend;
import net.runelite.api.FriendsChatManager;
import net.runelite.api.FriendsChatMember;
import net.runelite.api.FriendsChatRank;
import net.runelite.api.Player;
import net.runelite.api.clan.ClanChannel;
import net.runelite.api.clan.ClanChannelMember;
import net.runelite.api.clan.ClanRank;
import net.runelite.api.clan.ClanSettings;
import net.runelite.api.clan.ClanTitle;
import net.runelite.api.events.ClanChannelChanged;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.events.ConfigChanged;
import net.runelite.api.GameState;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ChatIconManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

@PluginDescriptor(
    name = "Show Friends On Login",
    description = "Shows a panel on login with online friends, clan chat members, and chat channel members, including rank icons",
    tags = {"friends", "online", "clan", "chat", "world", "rank", "overlay", "channel"}
)
public class FriendsOnlinePlugin extends Plugin
{
    @Inject
    private Client client;

    @Inject
    private FriendsOnlineConfig config;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private ChatIconManager chatIconManager;

    @Inject
    private SpriteManager spriteManager;

    private FriendsOnlineOverlay overlay;
    private List<PlayerLine> friendLines = Collections.emptyList();
    private List<PlayerLine> clanLines = Collections.emptyList();
    private List<PlayerLine> chatLines = Collections.emptyList();
    private int hideTicks = -1;
    private boolean shownOnce;
    private int dataRetries;

    private final Map<ClanRank, BufferedImage> clanRankCache = new HashMap<>();
    private final Map<Integer, BufferedImage> chatRankCache = new HashMap<>();

    @Provides
    FriendsOnlineConfig getConfig(ConfigManager configManager)
    {
        return configManager.getConfig(FriendsOnlineConfig.class);
    }

    public List<PlayerLine> getFriendLines()
    {
        return friendLines;
    }

    public List<PlayerLine> getClanLines()
    {
        return clanLines;
    }

    public List<PlayerLine> getChatLines()
    {
        return chatLines;
    }

    public String getChannelName()
    {
        return "Chat-channel";
    }

    public int getLocalWorld()
    {
        return client.getWorld();
    }

    public boolean getShowRanks()
    {
        return config.showRanks();
    }

    public FriendsOnlineConfig.SortMode getSortMode()
    {
        return config.sortMode();
    }

    @Override
    protected void startUp()
    {
        overlay = new FriendsOnlineOverlay(this);
        overlay.setVisible(false);
        overlayManager.add(overlay);
    }

    @Override
    protected void shutDown()
    {
        overlayManager.remove(overlay);
        friendLines = Collections.emptyList();
        clanLines = Collections.emptyList();
        chatLines = Collections.emptyList();
        hideTicks = -1;
        shownOnce = false;
        dataRetries = 0;
        clanRankCache.clear();
        chatRankCache.clear();
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() == GameState.LOGIN_SCREEN)
        {
            friendLines = Collections.emptyList();
            clanLines = Collections.emptyList();
            chatLines = Collections.emptyList();
            overlay.setVisible(false);
            hideTicks = -1;
            shownOnce = false;
            dataRetries = 0;
        }
    }

    @Subscribe
    public void onClanChannelChanged(ClanChannelChanged event)
    {
        if (event.getClanChannel() == null)
        {
            return;
        }

        clanLines = buildClanLines();

        if (overlay.isVisible())
        {
            overlay.invalidateData();
        }
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!event.getGroup().equals(FriendsOnlineConfig.GROUP))
        {
            return;
        }

        try
        {
            buildData();
        }
        catch (Exception | Error e)
        {
        }

        overlay.invalidateData();

        if (hasData())
        {
            overlay.setVisible(true);
            hideTicks = config.displayTime() > 0
                ? config.displayTime() * 1000 / 600
                : -1;
        }
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        if (client.getGameState() != GameState.LOGGED_IN)
        {
            return;
        }

        if (hideTicks > 0)
        {
            hideTicks--;
            if (hideTicks == 0)
            {
                overlay.setVisible(false);
                friendLines = Collections.emptyList();
                clanLines = Collections.emptyList();
                chatLines = Collections.emptyList();
                hideTicks = -1;
            }
            return;
        }

        if (dataRetries > 10)
        {
            return;
        }

        if (client.getTickCount() % 5 != 0)
        {
            return;
        }

        dataRetries++;

        buildData();

        if (hasData())
        {
            if (!shownOnce)
            {
                overlay.setVisible(true);
                shownOnce = true;
                if (config.displayTime() > 0)
                {
                    hideTicks = config.displayTime() * 1000 / 600;
                }
            }
            else
            {
                overlay.invalidateData();
            }
        }
    }

    private void buildData()
    {
        friendLines = buildFriendLines();
        clanLines = buildClanLines();
        chatLines = buildChatLines();
    }

    private boolean hasData()
    {
        return !friendLines.isEmpty() || !clanLines.isEmpty() || !chatLines.isEmpty();
    }

    private List<PlayerLine> buildFriendLines()
    {
        if (!config.showFriends())
        {
            return Collections.emptyList();
        }

        net.runelite.api.FriendContainer container = client.getFriendContainer();
        if (container == null)
        {
            return Collections.emptyList();
        }

        Friend[] friends = container.getMembers();
        if (friends == null)
        {
            return Collections.emptyList();
        }

        List<PlayerLine> lines = new ArrayList<>();
        boolean showWorld = config.showWorld();

        for (Friend friend : friends)
        {
            if (friend.getWorld() > 0)
            {
                String cleanName = Text.toJagexName(friend.getName());
                lines.add(new PlayerLine(cleanName, cleanName, showWorld ? friend.getWorld() : -1, -1));
            }
        }

        sortLines(lines);
        return trimLines(lines);
    }

    private List<PlayerLine> buildClanLines()
    {
        if (!config.showClanChat())
        {
            return Collections.emptyList();
        }

        ClanChannel channel = client.getClanChannel();
        ClanSettings settings = client.getClanSettings();
        if (channel == null)
        {
            channel = client.getGuestClanChannel();
            settings = client.getGuestClanSettings();
        }
        if (channel == null)
        {
            return Collections.emptyList();
        }

        List<ClanChannelMember> members = channel.getMembers();
        if (members == null || members.isEmpty())
        {
            return Collections.emptyList();
        }

        String localName = getLocalPlayerName();
        List<PlayerLine> lines = new ArrayList<>();
        boolean showWorld = config.showWorld();
        boolean showRanks = config.showRanks();

        for (ClanChannelMember member : members)
        {
            String cleanName = Text.toJagexName(member.getName());
            if (cleanName.equals(localName))
            {
                continue;
            }
            ClanRank clanRank = member.getRank();
            int rankValue = clanRank.getRank();
            PlayerLine pl = new PlayerLine(cleanName, cleanName, showWorld ? member.getWorld() : -1, rankValue);
            if (showRanks && rankValue > 0 && settings != null)
            {
                pl.rankImage = loadClanRankIcon(clanRank, settings);
            }
            lines.add(pl);
        }

        sortLines(lines);
        return trimLines(lines);
    }

    private List<PlayerLine> buildChatLines()
    {
        if (!config.showFriendsChat())
        {
            return Collections.emptyList();
        }

        FriendsChatManager manager = client.getFriendsChatManager();
        if (manager == null)
        {
            return Collections.emptyList();
        }

        FriendsChatMember[] members = manager.getMembers();
        if (members == null || members.length == 0)
        {
            return Collections.emptyList();
        }

        String localName = getLocalPlayerName();
        List<PlayerLine> lines = new ArrayList<>();
        boolean showWorld = config.showWorld();
        boolean showRanks = config.showRanks();

        for (FriendsChatMember member : members)
        {
            String cleanName = Text.toJagexName(member.getName());
            if (cleanName.equals(localName))
            {
                continue;
            }
            FriendsChatRank rank = member.getRank();
            int rankValue = rank.getValue();
            PlayerLine pl = new PlayerLine(cleanName, cleanName, showWorld ? member.getWorld() : -1, rankValue);
            if (showRanks && rankValue > 0)
            {
                pl.rankImage = loadFriendsChatRankIcon(rank);
            }
            lines.add(pl);
        }

        sortLines(lines);
        return trimLines(lines);
    }

    private String getLocalPlayerName()
    {
        return Optional.ofNullable(client.getLocalPlayer())
            .map(Player::getName)
            .map(Text::toJagexName)
            .orElse(null);
    }

    private BufferedImage loadClanRankIcon(ClanRank rank, ClanSettings clanSettings)
    {
        if (rank == null)
        {
            return null;
        }

        if (clanRankCache.containsKey(rank))
        {
            return clanRankCache.get(rank);
        }

        try
        {
            ClanTitle title = clanSettings.titleForRank(rank);
            if (title == null)
            {
                clanRankCache.put(rank, null);
                return null;
            }

            BufferedImage img = null;
            try
            {
                EnumComposition enumComp = client.getEnum(EnumID.CLAN_RANK_GRAPHIC);
                if (enumComp != null)
                {
                    int spriteId = enumComp.getIntValue(title.getId());
                    img = spriteManager.getSprite(spriteId, 0);
                }
            }
            catch (Exception e)
            {
            }

            clanRankCache.put(rank, img);
            return img;
        }
        catch (Error | Exception e)
        {
            clanRankCache.put(rank, null);
            return null;
        }
    }

    private BufferedImage loadFriendsChatRankIcon(FriendsChatRank rank)
    {
        int rankValue = rank.getValue();
        if (chatRankCache.containsKey(rankValue))
        {
            return chatRankCache.get(rankValue);
        }

        BufferedImage img = null;
        try
        {
            img = chatIconManager.getRankImage(rank);
        }
        catch (Exception e)
        {
        }

        chatRankCache.put(rankValue, img);
        return img;
    }

    private void sortLines(List<PlayerLine> lines)
    {
        FriendsOnlineConfig.SortMode mode = config.sortMode();

        if (mode == FriendsOnlineConfig.SortMode.WORLD)
        {
            Map<Integer, Integer> worldCounts = new HashMap<>();
            for (PlayerLine pl : lines)
            {
                if (!pl.moreLine && pl.world > 0)
                {
                    worldCounts.merge(pl.world, 1, Integer::sum);
                }
            }

            lines.sort((a, b) ->
            {
                if (a.moreLine) return 1;
                if (b.moreLine) return -1;

                boolean aHasWorld = a.world > 0;
                boolean bHasWorld = b.world > 0;
                if (aHasWorld != bHasWorld) return aHasWorld ? -1 : 1;

                if (aHasWorld)
                {
                    int cmp = Integer.compare(
                        worldCounts.getOrDefault(b.world, 0),
                        worldCounts.getOrDefault(a.world, 0));
                    if (cmp != 0) return cmp;
                    if (a.world != b.world) return Integer.compare(a.world, b.world);
                }

                return a.sortName.compareToIgnoreCase(b.sortName);
            });
            return;
        }

        Comparator<PlayerLine> c;

        if (mode == FriendsOnlineConfig.SortMode.RANK)
        {
            c = Comparator.<PlayerLine, Integer>comparing(pl -> pl.moreLine ? 0 : -pl.rank)
                .thenComparing(pl -> pl.moreLine ? "" : pl.sortName, String.CASE_INSENSITIVE_ORDER);
        }
        else
        {
            c = Comparator.<PlayerLine, Boolean>comparing(pl -> pl.moreLine)
                .thenComparing(pl -> pl.sortName, String.CASE_INSENSITIVE_ORDER);
        }

        lines.sort(c);
    }

    private List<PlayerLine> trimLines(List<PlayerLine> lines)
    {
        int max = config.maxPlayers();
        if (max > 0 && lines.size() > max)
        {
            int remaining = lines.size() - max;
            lines = new ArrayList<>(lines.subList(0, max));
            lines.add(new PlayerLine("+" + remaining + " more"));
        }
        return lines;
    }
}

package com.robisa693.onlinefriends;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;

class PlayerRowComponent implements LayoutableRenderableEntity
{
    private static final int ICON_GAP = 3;
    private static final int RIGHT_PAD = 2;

    private BufferedImage rankIcon;
    private String name;
    private String world;
    private Color worldColor;
    private Point preferredLocation = new Point();
    private Dimension preferredSize = new Dimension();
    private Rectangle bounds = new Rectangle();

    void setRankIcon(BufferedImage icon)
    {
        this.rankIcon = icon;
    }

    void setName(String name)
    {
        this.name = name;
    }

    void setWorld(String world)
    {
        this.world = world;
    }

    void setWorldColor(Color worldColor)
    {
        this.worldColor = worldColor;
    }

    @Override
    public void setPreferredLocation(Point p)
    {
        this.preferredLocation = p;
    }

    @Override
    public void setPreferredSize(Dimension d)
    {
        this.preferredSize = d;
    }

    @Override
    public Rectangle getBounds()
    {
        return bounds;
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        int x = preferredLocation.x;
        int y = preferredLocation.y;
        FontMetrics fm = graphics.getFontMetrics();
        int baseline = y + fm.getAscent();
        int rowHeight = fm.getHeight();

        if (rankIcon != null)
        {
            int iconY = y + (rowHeight - rankIcon.getHeight()) / 2;
            graphics.drawImage(rankIcon, x, iconY, null);
            x += rankIcon.getWidth() + ICON_GAP;
            rowHeight = Math.max(rowHeight, rankIcon.getHeight());
        }

        graphics.setColor(Color.WHITE);
        graphics.drawString(name, x, baseline);

        if (world != null)
        {
            int rightX = preferredLocation.x + preferredSize.width - fm.stringWidth(world) - RIGHT_PAD;
            graphics.setColor(worldColor != null ? worldColor : Color.WHITE);
            graphics.drawString(world, rightX, baseline);
        }

        bounds.setBounds(preferredLocation.x, preferredLocation.y, preferredSize.width, rowHeight);
        return new Dimension(preferredSize.width, rowHeight);
    }
}

package com.robisa693.onlinefriends;

import java.awt.image.BufferedImage;

class PlayerLine
{
    final String displayName;
    final String sortName;
    final int world;
    final int rank;
    final boolean moreLine;
    BufferedImage rankImage;

    PlayerLine(String displayName, String sortName, int world, int rank)
    {
        this.displayName = displayName;
        this.sortName = sortName;
        this.world = world;
        this.rank = rank;
        this.moreLine = false;
    }

    PlayerLine(String moreText)
    {
        this.displayName = moreText;
        this.sortName = moreText;
        this.world = -1;
        this.rank = -1;
        this.moreLine = true;
    }
}

package com.robisa693.onlinefriends;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.util.List;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.PanelComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

public class FriendsOnlineOverlay extends OverlayPanel
{
    private static final int COLUMN_GAP = 15;
    private static final int MIN_COLUMN_WIDTH = 100;
    private static final int LEFT_RIGHT_GAP = 10;
    private static final int HORIZONTAL_PADDING = 12;

    private FriendsOnlinePlugin plugin;
    private boolean visible;

    private final PanelComponent friendsPanel = new PanelComponent();
    private final PanelComponent clanPanel = new PanelComponent();
    private final PanelComponent chatPanel = new PanelComponent();
    private boolean populated;

    @Inject
    public FriendsOnlineOverlay(FriendsOnlinePlugin plugin)
    {
        this.plugin = plugin;
        setPosition(OverlayPosition.TOP_LEFT);
    }

    public void setVisible(boolean visible)
    {
        this.visible = visible;
        populated = false;
    }

    public boolean isVisible()
    {
        return visible;
    }

    public void invalidateData()
    {
        populated = false;
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!visible)
        {
            return null;
        }

        List<PlayerLine> friendLines = plugin.getFriendLines();
        List<PlayerLine> clanLines = plugin.getClanLines();
        List<PlayerLine> chatLines = plugin.getChatLines();

        if ((friendLines == null || friendLines.isEmpty())
            && (clanLines == null || clanLines.isEmpty())
            && (chatLines == null || chatLines.isEmpty()))
        {
            return null;
        }

        if (!populated)
        {
            int localWorld = plugin.getLocalWorld();
            populatePanel(friendsPanel, "Friends", friendLines, localWorld);
            populatePanel(clanPanel, "Clan Chat", clanLines, localWorld);
            populatePanel(chatPanel, "Chat-channel", chatLines, localWorld);
            populated = true;

            FontMetrics fm = graphics.getFontMetrics();
            sizePanelToContent(friendsPanel, fm, "Friends", friendLines);
            sizePanelToContent(clanPanel, fm, "Clan Chat", clanLines);
            sizePanelToContent(chatPanel, fm, "Chat-channel", chatLines);

            Graphics2D warmup = (Graphics2D) graphics.create();
            warmup.setClip(0, 0, 0, 0);
            for (PanelComponent p : new PanelComponent[]{friendsPanel, clanPanel, chatPanel})
            {
                if (!p.getChildren().isEmpty())
                {
                    p.setPreferredLocation(new Point(0, 0));
                    p.render(warmup);
                }
            }
            warmup.dispose();
        }

        PanelComponent[] panels = {friendsPanel, clanPanel, chatPanel};
        int x = 0;
        int totalHeight = 0;

        for (PanelComponent panel : panels)
        {
            if (panel.getChildren().isEmpty()) continue;

            panel.setPreferredLocation(new Point(x, 0));
            Dimension dim = panel.render(graphics);

            x += dim.width + COLUMN_GAP;
            totalHeight = Math.max(totalHeight, dim.height);
        }

        if (x == 0)
        {
            return null;
        }

        return new Dimension(x - COLUMN_GAP, totalHeight);
    }

    private static String worldString(PlayerLine line)
    {
        if (line.world > 0) return Integer.toString(line.world);
        return null;
    }

    private static int rankIconWidth(PlayerLine line)
    {
        if (line.rankImage != null) return line.rankImage.getWidth() + 3;
        return 0;
    }

    private static void populatePanel(PanelComponent panel, String title, List<PlayerLine> lines, int localWorld)
    {
        panel.getChildren().clear();

        if (lines == null || lines.isEmpty())
        {
            return;
        }

        long actualCount = lines.stream().filter(l -> !l.moreLine).count();
        panel.getChildren().add(TitleComponent.builder()
            .text(title + " (" + actualCount + "):")
            .build());

        for (PlayerLine line : lines)
        {
            if (line.moreLine)
            {
                panel.getChildren().add(LineComponent.builder()
                    .left(line.displayName)
                    .build());
                continue;
            }

            Color worldColor = null;
            String ws = worldString(line);
            if (ws != null)
            {
                worldColor = line.world == localWorld ? Color.GREEN : Color.YELLOW;
            }

            PlayerRowComponent row = new PlayerRowComponent();
            row.setRankIcon(line.rankImage);
            row.setName(line.displayName);
            row.setWorld(ws);
            row.setWorldColor(worldColor);
            panel.getChildren().add(row);
        }
    }

    private static void sizePanelToContent(PanelComponent panel, FontMetrics fm, String title, List<PlayerLine> lines)
    {
        if (lines == null || lines.isEmpty())
        {
            return;
        }

        long actualCount = lines.stream().filter(l -> !l.moreLine).count();
        int maxWidth = fm.stringWidth(title + " (" + actualCount + "):");

        for (PlayerLine line : lines)
        {
            int width = rankIconWidth(line) + fm.stringWidth(line.displayName);
            String ws = worldString(line);
            if (ws != null)
            {
                width += LEFT_RIGHT_GAP + fm.stringWidth(ws);
            }
            maxWidth = Math.max(maxWidth, width);
        }

        int panelWidth = Math.max(MIN_COLUMN_WIDTH, maxWidth + HORIZONTAL_PADDING);
        panel.setPreferredSize(new Dimension(panelWidth, 0));
    }
}
